public final class R9StyleChecks implements FabricClientGameTest {public void runTest(ClientGameTestContext t){t.getInput().resizeWindow(1440,900);t.runOnClient(c->{LibraryState.accept("library-onboarding-v2");LibraryState.select(LibraryState.Theme.SAKURA);c.options.getGuiScale().setValue(2);c.onResolutionChanged();dev.dwmir.countit.Config.current=new dev.dwmir.countit.Config();});try(var w=t.worldBuilder().create()){w.getClientWorld().waitForChunksRender();t.setScreen(()->null);t.runOnClient(c->{c.player.getInventory().setStack(0,new net.minecraft.item.ItemStack(net.minecraft.item.Items.TOTEM_OF_UNDYING));c.player.getInventory().setStack(40,new net.minecraft.item.ItemStack(net.minecraft.item.Items.TOTEM_OF_UNDYING));dev.dwmir.countit.Config.current.handScale=1;});t.waitTicks(12);t.takeScreenshot("r9-held-scale-1");t.runOnClient(c->dev.dwmir.countit.Config.current.handScale=.5f);t.waitTicks(8);t.takeScreenshot("r9-held-scale-half");t.runOnClient(c->dev.dwmir.countit.Config.current.handScale=1);for(int i=0;i<4;i++){final int style=i;t.runOnClient(c->me.shedaniel.autoconfig.AutoConfig.getConfigHolder(net.customcrossbowsounds.config.CustomCrossbowSoundsConfig.class).getConfig().effectHudStyle=style);t.setScreen(()->new net.customcrossbowsounds.client.SettingsScreen(null));t.runOnClient(c->((net.customcrossbowsounds.client.SettingsScreen)WorkspaceScreen.actual(c.currentScreen)).selectPage(2));t.waitTicks(9);t.takeScreenshot("r9-crossbow-style-"+i);}t.setScreen(()->new dev.dwmir.countit.SettingsScreen(null));t.waitTicks(8);t.takeScreenshot("r9-countit-counter");t.setScreen(()->DwmirLib.createScreen(null));t.getInput().setCursorPos(0,0);t.waitTicks(8);t.takeScreenshot("r9-library-six");}t.setScreen(()->null);System.out.println("DWMIR_R9_STYLE_CHECKS_PASS");}}
